mapper.update:

		/*updateKePReporStatustDt*/
		UPDATE KEP_REPORT_DT 
		  SET STATUS = #{REPORT_STATUS}            
               , CHANGE_DATE = SYSDATE  
               , CHANGE_USER_ID = #{USER_ID} 
	      WHERE REPORT_NO IN (
					       		SELECT A.PO_NO FROM KEPMGPDT A
					       		WHERE BUYER = #{COM_CODE}
					           	AND PM_NO = #{KEY_1}
	       					  )


		/*updateRejectReportKEPMGPHD*/
		UPDATE KEPMGPHD 
		  SET STATUS = #{STATUS}            
               , CONFIRM_DATE = SYSDATE  
               , CONFIRM_USER_ID = #{USER_ID} 
               , CHANGE_DATE = SYSDATE
	       WHERE BUYER = #{COM_CODE}
	           AND PM_NO = #{KEY_1}


		/*updateRejectReportKEPMGPDT*/
		UPDATE KEPMGPDT 
		  SET STATUS = #{STATUS}            
               , CONFIRM_DATE = SYSDATE  
               , CONFIRM_USER_ID = #{USER_ID} 
               , CHANGE_DATE = SYSDATE
	       WHERE BUYER = #{COM_CODE}
	           AND PM_NO = #{KEY_1}


		/*updateCancelReportKEPMGPHD*/
		UPDATE KEPMGPHD 
		  SET STATUS = #{STATUS}            
               , CHANGE_DATE = SYSDATE
	       WHERE BUYER = #{COM_CODE}
	           AND PM_NO = #{KEY_1}


		/*updateCancelReportKEPMGPDT*/
		UPDATE KEPMGPDT 
		  SET STATUS = #{STATUS}            
               , CHANGE_DATE = SYSDATE  
	       WHERE BUYER = #{COM_CODE}
	           AND PM_NO = #{KEY_1}


		/*updateApprovalReportKEPMGPHD*/
		UPDATE KEPMGPHD 
		  SET STATUS = #{STATUS}            
               , CONFIRM_DATE = SYSDATE  
               , CONFIRM_USER_ID = #{USER_ID} 
               , CONFIRM_USER_DEPT =  #{USER_DEPT}
               , CHANGE_DATE = SYSDATE
	       WHERE BUYER = #{COM_CODE}
	           AND PM_NO = #{KEY_1}


		/*updateApprovalReportKEPMGPDT*/
		UPDATE KEPMGPDT 
		  SET STATUS = #{STATUS}            
               , CHANGE_DATE = SYSDATE  
	       WHERE BUYER = #{COM_CODE}
	           AND PM_NO = #{KEY_1}
